def words(text, keep_punctuation=False, case_sensitive=True):
    out = []
    for chunk in text.split():
        if not case_sensitive:
            chunk = chunk.lower()
        core = chunk.strip(".,;:!?\"'()")
        trailing = chunk[len(core):] if chunk.endswith(tuple(".,;:!?\"')")) else ""
        if core:
            out.append(core)
        if keep_punctuation and trailing:
            out.extend(trailing)
    return out

